steps.content:
# By changing the setting below to TRUE you are indicating your agreement to our EULA (https://aka.ms/MinecraftEULA).
# Configured on {{ now("%Y-%m-%d") }}
eula=true

# Minecraft server properties
motd={{ motd }}
server-port={{ server.port | default(25565, true) }}
gamemode={{ gamemode }}
difficulty={{ difficulty }}
max-players={{ max_players }}
pvp={{ "true" if pvp == "1" else "false" }}
white-list={{ "true" if whitelist == "1" else "false" }}
enforce-whitelist={{ "true" if whitelist == "1" else "false" }}
view-distance={{ view_distance }}
online-mode={{ "true" if online_mode == "1" else "false" }}
enable-rcon=false
